    "code": "import 'package:flutter/material.dart';\n\nclass SenseDetailScreen extends StatelessWidget {\n  final Map<String, dynamic> sense;\n  final VoidCallback onBack;\n\n  const SenseDetailScreen({\n    super.key,\n    required this.sense,\n    required this.onBack,\n  });\n\n  @override\n  Widget build(BuildContext context) {\n    final color = sense['color'] as Color? ?? const Color(0xFF3B82F6);\n    final List strengths = sense['strengths'] as List? ?? [];\n    final List learnBestWith = sense['learnBestWith'] as List? ?? [];\n    final List careers = sense['careers'] as List? ?? [];\n\n    return Scaffold(\n      backgroundColor: const Color(0xFFF8FAFC),\n      appBar: AppBar(\n        leading: IconButton(\n          icon: const Icon(Icons.arrow_back_ios_new, size: 20),\n          onPressed: onBack,\n        ),\n        title: Text(\n          sense['name'] ?? '',\n          style: const TextStyle(fontWeight: FontWeight.bold, fontSize: 17, color: Color(0xFF0F172A)),\n        ),\n        centerTitle: true,\n      ),\n      body: SingleChildScrollView(\n        padding: const EdgeInsets.symmetric(horizontal: 16, vertical: 12),\n        child: Column(\n          crossAxisAlignment: CrossAxisAlignment.start,\n          children: [\n            // Hero Score Banner\n            Container(\n              padding: const EdgeInsets.all(20),\n              decoration: BoxDecoration(\n                color: Colors.white,\n                borderRadius: BorderRadius.circular(24),\n                border: Border.all(color: color.withOpacity(0.3), width: 1.5),\n                boxShadow: [\n                  BoxShadow(\n                    color: color.withOpacity(0.08),\n                    blurRadius: 16,\n                    offset: const Offset(0, 4),\n                  ),\n                ],\n              ),\n              child: Row(\n                children: [\n                  Container(\n                    width: 64,\n                    height: 64,\n                    decoration: BoxDecoration(\n                      shape: BoxShape.circle,\n                      color: color.withOpacity(0.15),\n                      border: Border.all(color: color, width: 2.5),\n                    ),\n                    alignment: Alignment.center,\n                    child: Text(\n                      '${(sense['score'] as double? ?? 80).toInt()}%',\n                      style: TextStyle(fontSize: 16, fontWeight: FontWeight.bold, color: color),\n                    ),\n                  ),\n                  const SizedBox(width: 16),\n                  Expanded(\n                    child: Column(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Text(\n                          sense['typeName'] ?? '',\n                          style: TextStyle(fontSize: 11, fontWeight: FontWeight.bold, color: color),\n                        ),\n                        const SizedBox(height: 2),\n                        Text(\n                          sense['name'] ?? '',\n                          style: const TextStyle(fontSize: 16, fontWeight: FontWeight.bold, color: Color(0xFF0F172A)),\n                        ),\n                        const SizedBox(height: 4),\n                        Text(\n                          sense['description'] ?? '',\n                          style: const TextStyle(fontSize: 12, color: Color(0xFF64748B), height: 1.35),\n                        ),\n                      ],\n                    ),\n                  ),\n                ],\n              ),\n            ),\n\n            const SizedBox(height: 18),\n\n            // How Student Learns Best\n            const Text(\n              'How You Learn Best',\n              style: TextStyle(fontSize: 14, fontWeight: FontWeight.bold, color: Color(0xFF0F172A)),\n            ),\n            const SizedBox(height: 10),\n            Container(\n              padding: const EdgeInsets.all(16),\n              decoration: BoxDecoration(\n                color: Colors.white,\n                borderRadius: BorderRadius.circular(18),\n                border: Border.all(color: const Color(0xFFE2E8F0)),\n              ),\n              child: Column(\n                children: learnBestWith.map((item) {\n                  return Padding(\n                    padding: const EdgeInsets.only(bottom: 8.0),\n                    child: Row(\n                      crossAxisAlignment: CrossAxisAlignment.start,\n                      children: [\n                        Icon(Icons.check_circle_outline, size: 16, color: color),\n                        const SizedBox(width: 10),\n                        Expanded(\n                          child: Text(\n                            item.toString(),\n                            style: const TextStyle(fontSize: 12, color: Color(0xFF334155), height: 1.4),\n                          ),\n                        ),\n                      ],\n                    ),\n                  );\n                }).toList(),\n              ),\n            ),\n\n            const SizedBox(height: 18),\n\n            // Careers\n            const Text(\n              'Aligned Career Fields',\n              style: TextStyle(fontSize: 14, fontWeight: FontWeight.bold, color: Color(0xFF0F172A)),\n            ),\n            const SizedBox(height: 10),\n            Wrap(\n              spacing: 8,\n              runSpacing: 8,\n              children: careers.map((c) {\n                return Container(\n                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 8),\n                  decoration: BoxDecoration(\n                    color: Colors.white,\n                    borderRadius: BorderRadius.circular(12),\n                    border: Border.all(color: const Color(0xFFCBD5E1)),\n                  ),\n                  child: Text(\n                    c.toString(),\n                    style: const TextStyle(fontSize: 12, fontWeight: FontWeight.w600, color: Color(0xFF0F172A)),\n                  ),\n                );\n              }).toList(),\n            ),\n          ],\n        ),\n      ),\n    );\n  }\n}\n"
