    "code": "name: daksh_hybrid\ndescription: \"Daksh - Multi-Intelligence & Career Hybrid Mobile Platform\"\npublish_to: \"none\"\nversion: 1.0.0+1\n\nenvironment:\n  sdk: \">=3.2.0 <4.0.0\"\n  flutter: \">=3.16.0\"\n\ndependencies:\n  flutter:\n    sdk: flutter\n\n  # Hybrid WebView & Bidirectional JavaScript Bridge\n  flutter_inappwebview: ^6.1.5\n  webview_flutter: ^4.10.0\n\n  # Native UI, Charts & Icons\n  fl_chart: ^0.70.2\n  google_fonts: ^6.2.1\n  lucide_icons: ^0.257.0\n\n  # AI Mentor & Generative AI (Gemini 2.5/Flash)\n  google_generative_ai: ^0.4.6\n  http: ^1.2.2\n\n  # Device Hardware, Haptics & Local Storage\n  shared_preferences: ^2.5.2\n  path_provider: ^2.1.5\n  share_plus: ^10.1.4\n  flutter_local_notifications: ^18.0.1\n  pdf: ^3.11.2\n  printing: ^5.13.2\n  url_launcher: ^6.3.1\n\ndev_dependencies:\n  flutter_test:\n    sdk: flutter\n  flutter_lints: ^5.0.0\n\nflutter:\n  uses-material-design: true\n  assets:\n    - assets/\n    - assets/web/\n"
